private fun time(ms:Long):String { val s=(ms.coerceAtLeast(0))/1000; return "%d:%02d".format(s/60,s%60) }

@Composable fun HomeScreen(viewModel:MusicPlayerViewModel,uiState:MusicUiState,onTrackClick:()->Unit){
 val tracks=uiState.tracks.filter{(it.title+it.artist+it.album).contains(uiState.query,true)}
 Column(Modifier.fillMaxSize().background(DeepBlack).padding(horizontal=18.dp)){
  Spacer(Modifier.height(20.dp));Text("BESTBOY SOUNDS",color=ElectricViolet,fontWeight=FontWeight.Bold);Text("Ta musique, ton univers.",color=TextPrimary,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.ExtraBold)
  Spacer(Modifier.height(16.dp));OutlinedTextField(value=uiState.query,onValueChange=viewModel::setQuery,modifier=Modifier.fillMaxWidth(),placeholder={Text("Rechercher un morceau...")},leadingIcon={Icon(Icons.Rounded.Search,null)},singleLine=true,shape=RoundedCornerShape(15.dp),colors=OutlinedTextFieldDefaults.colors(focusedBorderColor=ElectricViolet,unfocusedBorderColor=BorderPurple,focusedTextColor=TextPrimary,unfocusedTextColor=TextPrimary))
  Spacer(Modifier.height(16.dp));Row(verticalAlignment=Alignment.CenterVertically){Text("Ma bibliothèque",color=TextPrimary,style=MaterialTheme.typography.titleLarge,modifier=Modifier.weight(1f));Text("${tracks.size} titres",color=TextMuted);IconButton(onClick=viewModel::loadTracks){Icon(Icons.Rounded.Refresh,"Actualiser",tint=ElectricViolet)}}
  if(tracks.isEmpty()){Column(Modifier.fillMaxSize(),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Icon(Icons.Rounded.LibraryMusic,null,tint=ElectricViolet,modifier=Modifier.size(58.dp));Spacer(Modifier.height(12.dp));Text(if(uiState.tracks.isEmpty())"Aucune chanson trouvée" else "Aucun résultat",color=TextPrimary);Text("Ajoute des fichiers MP3 sur ton téléphone puis actualise.",color=TextMuted);Button(onClick=viewModel::loadTracks){Text("Actualiser")}}}
  else LazyColumn(contentPadding=PaddingValues(bottom=18.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){items(tracks,key={it.id}){t->Row(Modifier.fillMaxWidth().background(CardPurple,RoundedCornerShape(14.dp)).clickable{viewModel.playTrack(t);onTrackClick()}.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(44.dp).background(ElevatedPurple,RoundedCornerShape(12.dp)),contentAlignment=Alignment.Center){Icon(Icons.Rounded.MusicNote,null,tint=ElectricViolet)};Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(t.title,color=TextPrimary,maxLines=1,fontWeight=FontWeight.SemiBold);Text(t.artist,color=TextMuted,maxLines=1,style=MaterialTheme.typography.bodySmall)};Text(time(t.durationMs),color=TextMuted,style=MaterialTheme.typography.labelSmall);IconButton(onClick={viewModel.playTrack(t);onTrackClick()}){Icon(Icons.Rounded.PlayCircle,null,tint=ElectricViolet)}}}}
 }
}

@Composable fun NowPlayingScreen(viewModel:MusicPlayerViewModel,uiState:MusicUiState,onBackClick:()->Unit){val t=uiState.currentTrack?:return;val p=if(uiState.durationMs>0)(uiState.currentPositionMs.toFloat()/uiState.durationMs).coerceIn(0f,1f) else 0f
 Column(Modifier.fillMaxSize().background(DeepBlack).padding(22.dp),horizontalAlignment=Alignment.CenterHorizontally){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){IconButton(onClick=onBackClick){Icon(Icons.Rounded.KeyboardArrowDown,"Retour",tint=TextPrimary)};Text("LECTURE EN COURS",color=ElectricViolet,fontWeight=FontWeight.Bold);Spacer(Modifier.weight(1f));IconButton(onClick=viewModel::toggleFavorite){Icon(if(t.id in uiState.favoriteIds)Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder,"Favori",tint=AccentCoral)}};Spacer(Modifier.weight(1f));Box(Modifier.fillMaxWidth().aspectRatio(1f).background(ElevatedPurple,RoundedCornerShape(26.dp)),contentAlignment=Alignment.Center){Icon(Icons.Rounded.Album,null,tint=ElectricViolet,modifier=Modifier.size(145.dp))};Spacer(Modifier.height(25.dp));Text(t.title,color=TextPrimary,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,maxLines=2);Text(t.artist,color=TextMuted,style=MaterialTheme.typography.titleMedium);Spacer(Modifier.height(24.dp));Slider(value=p,onValueChange={if(uiState.durationMs>0)viewModel.seekTo((it*uiState.durationMs).toLong())},colors=SliderDefaults.colors(thumbColor=ElectricViolet,activeTrackColor=ElectricViolet));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(time(uiState.currentPositionMs),color=TextMuted);Text(time(uiState.durationMs),color=TextMuted)};Spacer(Modifier.height(14.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly,verticalAlignment=Alignment.CenterVertically){IconButton(onClick=viewModel::toggleShuffle){Icon(Icons.Rounded.Shuffle,"Aléatoire",tint=if(uiState.shuffle)ElectricViolet else TextMuted)};IconButton(onClick=viewModel::skipPrevious){Icon(Icons.Rounded.SkipPrevious,"Précédent",tint=TextPrimary,modifier=Modifier.size(36.dp))};FilledIconButton(onClick=viewModel::togglePlayPause,modifier=Modifier.size(72.dp),colors=IconButtonDefaults.filledIconButtonColors(containerColor=ElectricViolet)){Icon(if(uiState.isPlaying)Icons.Rounded.Pause else Icons.Rounded.PlayArrow,"Lecture/Pause",tint=DeepBlack,modifier=Modifier.size(40.dp))};IconButton(onClick=viewModel::skipNext){Icon(Icons.Rounded.SkipNext,"Suivant",tint=TextPrimary,modifier=Modifier.size(36.dp))};IconButton(onClick=viewModel::cycleRepeat){Icon(if(uiState.repeatMode==2)Icons.Rounded.RepeatOne else Icons.Rounded.Repeat,"Répéter",tint=if(uiState.repeatMode!=0)ElectricViolet else TextMuted)}};Spacer(Modifier.weight(1f))}
}

@Composable fun PlaylistsScreen(viewModel:MusicPlayerViewModel,uiState:MusicUiState){var name by remember{mutableStateOf("")};Column(Modifier.fillMaxSize().background(DeepBlack).padding(18.dp)){Text("Playlists",color=TextPrimary,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text("Organise tes morceaux préférés.",color=TextMuted);Spacer(Modifier.height(18.dp));Row(verticalAlignment=Alignment.CenterVertically){OutlinedTextField(value=name,onValueChange={name=it},modifier=Modifier.weight(1f),placeholder={Text("Nom de la playlist")},singleLine=true);IconButton(onClick={viewModel.addPlaylist(name);name=""}){Icon(Icons.Rounded.AddCircle,"Créer",tint=ElectricViolet,modifier=Modifier.size(32.dp))}};Spacer(Modifier.height(14.dp));uiState.playlists.forEach{p->Row(Modifier.fillMaxWidth().padding(vertical=5.dp).background(CardPurple,RoundedCornerShape(14.dp)).padding(16.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Rounded.QueueMusic,null,tint=ElectricViolet);Spacer(Modifier.width(12.dp));Text(p,color=TextPrimary,modifier=Modifier.weight(1f));Text(if(p=="Favoris")"${uiState.favoriteIds.size}" else "Playlist",color=TextMuted)}}}}

@Composable fun SettingsScreen(viewModel:MusicPlayerViewModel,uiState:MusicUiState){Column(Modifier.fillMaxSize().background(DeepBlack).padding(20.dp)){Text("Paramètres",color=TextPrimary,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Spacer(Modifier.height(18.dp));Text("BESTBOY SOUNDS",color=ElectricViolet,fontWeight=FontWeight.Bold);Text("Version 1.0.0",color=TextMuted);Spacer(Modifier.height(22.dp));Row(Modifier.fillMaxWidth().background(CardPurple,RoundedCornerShape(14.dp)).padding(16.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Rounded.MusicNote,null,tint=ElectricViolet);Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("Bibliothèque musicale",color=TextPrimary);Text("${uiState.tracks.size} morceaux détectés",color=TextMuted,style=MaterialTheme.typography.bodySmall)};TextButton(onClick=viewModel::loadTracks){Text("Actualiser")}};Spacer(Modifier.height(14.dp));Text("Les publicités Google AdMob utilisent les identifiants de test Google.",color=TextMuted,style=MaterialTheme.typography.bodySmall)}}
